body { font-family: system-ui; padding: 24px; }
label { display: block; margin-top: 12px; font-weight: 600; }
input { display: block; padding: 8px; margin-top: 4px; }
button { margin-top: 16px; padding: 8px 16px; }
button:focus-visible, input:focus-visible { outline: 2px solid #2563eb; }

body { font-family: system-ui; margin: 0; }
header, main { padding: 16px; }
.skip-link { position: absolute; left: -999px; top: 0; background: #111827; color: #fff; padding: 8px 12px; }
.skip-link:focus { left: 8px; }
a:focus-visible { outline: 2px solid #2563eb; }

body { font-family: system-ui; padding: 24px; }
